/**
 * Normalize 2B orchestrator input (JSON-only)
 * Note: Idempotency is handled by router's "Mark as Processing" step
 * which sets execution_status='processing' before calling this webhook.
 *
 * This also resolves canonical manifest keys without assuming Book 1 pathing.
 */
const input = $json || {};
const body = input.body && input.body !== input ? input.body : input;

const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');
const toStringValue = (value) => {
  if (value === undefined || value === null) return null;
  const trimmed = String(value).trim();
  if (!trimmed) return null;
  const lowered = trimmed.toLowerCase();
  return lowered === 'null' || lowered === 'undefined' ? null : trimmed;
};
const extractManifestKey = (value) => {
  const raw = toStringValue(value);
  if (!raw) return null;
  const withoutQuery = raw.split('?')[0];
  const marker = '/api/manifests/';
  if (withoutQuery.includes(marker)) {
    return withoutQuery.split(marker)[1].replace(/^\/+/, '');
  }
  try {
    if (withoutQuery.startsWith('http://') || withoutQuery.startsWith('https://')) {
      const url = new URL(withoutQuery);
      return url.pathname.replace(/^\/api\/manifests\//, '').replace(/^\/+/, '');
    }
  } catch {}
  return withoutQuery.replace(/^\/+/, '');
};
const extractBookIdFromKey = (value) => {
  const manifestKey = extractManifestKey(value);
  if (!manifestKey) return null;
  const marker = '/orders/';
  const index = manifestKey.indexOf(marker);
  return index > 0 ? manifestKey.slice(0, index) : null;
};
const toManifestUrl = (base, manifestKey) => {
  const normalizedBase = String(base || 'https://admin.littleherolabs.com').replace(/\/$/, '');
  const normalizedKey = String(manifestKey || '').replace(/^\/+/, '');
  return `${normalizedBase}/api/manifests/${normalizedKey}`;
};

const backendUrl = pick(input.backendUrl, body.backendUrl, 'https://admin.littleherolabs.com');
const orderId = pick(input.orderId, input.amazonOrderId, body.orderId, body.amazonOrderId, null);
if (!orderId) throw new Error('2B main: orderId is required');

const rawManifest2a = pick(
  input.manifestUrl,
  input.manifest2aUrl,
  input.manifest2aKey,
  input.originalManifestUrl,
  input.manifestKey,
  body.manifestUrl,
  body.manifest2aUrl,
  body.manifest2aKey,
  body.originalManifestUrl,
  body.manifestKey,
  null,
);
const rawOneManifest = pick(
  input.oneManifestUrl,
  input.oneManifestKey,
  input.one_manifest_url,
  body.oneManifestUrl,
  body.oneManifestKey,
  body.one_manifest_url,
  null,
);

const fallbackBookId = pick(
  input.bookId,
  body.bookId,
  extractBookIdFromKey(rawManifest2a),
  extractBookIdFromKey(rawOneManifest),
  'book-mvp-simple-adventure',
);
const manifest2aKey =
  extractManifestKey(rawManifest2a) ||
  `${fallbackBookId}/orders/${String(orderId)}/manifests/2a-manifest.json`;
const bookId = extractBookIdFromKey(manifest2aKey) || fallbackBookId;
const manifest2bKey =
  extractManifestKey(pick(input.manifest2bUrl, input.manifest2bKey, body.manifest2bUrl, body.manifest2bKey, null)) ||
  `${bookId}/orders/${String(orderId)}/manifests/2b-manifest.json`;
const oneManifestKey =
  extractManifestKey(rawOneManifest) ||
  `${bookId}/orders/${String(orderId)}/manifests/1-manifest.json`;

const manifest2aUrl = toManifestUrl(backendUrl, manifest2aKey);
const manifest2bUrl = toManifestUrl(backendUrl, manifest2bKey);
const oneManifestUrl = toManifestUrl(backendUrl, oneManifestKey);
const callbackUrl = pick(input.callbackUrl, body.callbackUrl, `${backendUrl}/webhook/2b-callback`);
const sw1WorkflowId = pick(input.sw1WorkflowId, body.sw1WorkflowId, null);
const batchSize = 1;
const force = !!pick(input.force, body.force, false);

return [{
  json: {
    orderId,
    bookId,
    backendUrl,
    manifestUrl: manifest2aUrl,
    manifest2aKey,
    manifest2aUrl,
    manifest2bKey,
    manifest2bUrl,
    oneManifestKey,
    oneManifestUrl,
    callbackUrl,
    sw1WorkflowId,
    batchSize,
    force,
  },
}];

/**
 * Build pose worklist (idempotent + replacement-aware).
 * Uses companion W0 manifest semantics when available so W2B only targets
 * the required pose set for the resolved book/format.
 */
const manifest2a = $items('Download 2A Manifest', 0, $runIndex)?.[0]?.json || {};
if (!manifest2a.schema) throw new Error('2B main: expected manifest JSON from Download 2A Manifest');

let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}

const LEGACY_REQUIRED_POSES = Array.from({ length: 12 }, (_, index) => index + 1);
const toStringValue = (value) => {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
};
const toObject = (value) => (value && typeof value === 'object' && !Array.isArray(value) ? value : null);
const toPoseNumber = (value) => {
  if (typeof value === 'number' && Number.isInteger(value) && value >= 0) return value;
  if (typeof value !== 'string' || value.trim().length === 0) return null;
  const parsed = Number.parseInt(value, 10);
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : null;
};
const uniqueSorted = (values) => [...new Set(values)].sort((left, right) => left - right);
const extractManifestKey = (value) => {
  const raw = toStringValue(value);
  if (!raw) return null;
  const withoutQuery = raw.split('?')[0];
  const marker = '/api/manifests/';
  if (withoutQuery.includes(marker)) {
    return withoutQuery.split(marker)[1].replace(/^\/+/, '');
  }
  try {
    if (withoutQuery.startsWith('http://') || withoutQuery.startsWith('https://')) {
      const url = new URL(withoutQuery);
      return url.pathname.replace(/^\/api\/manifests\//, '').replace(/^\/+/, '');
    }
  } catch {}
  return withoutQuery.replace(/^\/+/, '');
};
const extractBookIdFromManifestKey = (value) => {
  const manifestKey = extractManifestKey(value);
  if (!manifestKey) return null;
  const marker = '/orders/';
  const index = manifestKey.indexOf(marker);
  return index > 0 ? manifestKey.slice(0, index) : null;
};
const toManifestUrl = (base, manifestKey) => {
  const normalizedBase = String(base || 'https://admin.littleherolabs.com').replace(/\/$/, '');
  const normalizedKey = String(manifestKey || '').replace(/^\/+/, '');
  return `${normalizedBase}/api/manifests/${normalizedKey}`;
};
const asManifest = (raw) => {
  if (!raw) return null;
  if (raw.schema) return raw;
  const text = typeof raw === 'string' ? raw : (raw.data || raw.body || null);
  if (!text || typeof text !== 'string') return null;
  try {
    const parsed = JSON.parse(text);
    return parsed && parsed.schema ? parsed : null;
  } catch {
    return null;
  }
};
const loadManifest = async (rawValue, backendUrl) => {
  const manifestKey = extractManifestKey(rawValue);
  if (!manifestKey) return { manifestKey: null, manifest: null };
  const url = toManifestUrl(backendUrl, manifestKey) + '?v=' + Date.now();
  try {
    const raw = await this.helpers.httpRequest({ method: 'GET', url, json: false, timeout: 90000 });
    return { manifestKey, manifest: asManifest(raw) };
  } catch {
    return { manifestKey, manifest: null };
  }
};

const order = toObject(manifest2a.order) || {};
const backendUrl = ctx.backendUrl || 'https://admin.littleherolabs.com';
const callbackUrl = ctx.callbackUrl;
const orderId = ctx.orderId || toStringValue(manifest2a.orderId) || toStringValue(order.amazonOrderId) || toStringValue(order.orderId);
const characterHash = toStringValue(manifest2a.characterHash) || toStringValue(order.characterHash) || null;
if (!orderId) throw new Error('2B main: orderId missing after manifest download');
if (!characterHash) throw new Error('2B main: characterHash missing');

const manifest2aKey = extractManifestKey(ctx.manifest2aKey || ctx.manifest2aUrl) || `${ctx.bookId || 'book-mvp-simple-adventure'}/orders/${String(orderId)}/manifests/2a-manifest.json`;
const manifest2aUrl = ctx.manifest2aUrl || toManifestUrl(backendUrl, manifest2aKey);
const defaultBookId = extractBookIdFromManifestKey(manifest2aKey) || ctx.bookId || 'book-mvp-simple-adventure';
const oneManifestHint = toStringValue(order.oneManifestUrl) || ctx.oneManifestKey || ctx.oneManifestUrl || `${defaultBookId}/orders/${String(orderId)}/manifests/1-manifest.json`;
const { manifestKey: oneManifestKey, manifest: oneManifest } = await loadManifest(oneManifestHint, backendUrl);

let bookId = extractBookIdFromManifestKey(oneManifestKey) || defaultBookId;
let formatId = toStringValue(toObject(order.bookSpecs)?.formatId) || null;
let requiredPoseNumbers = [...LEGACY_REQUIRED_POSES];
let requiredPoseSource = 'legacy-default';

if (oneManifest && oneManifest.schema === 'lhb.run-manifest@v3') {
  const book = toObject(oneManifest.book) || {};
  const bookConfigRef = toObject(book.bookConfigRef) || {};
  const resolved = toObject(book.resolved) || {};
  const qaPolicy = toObject(resolved.qaPolicy) || {};
  const posePolicy = toObject(qaPolicy.pose) || {};
  const resolvedRequired = Array.isArray(posePolicy.requiredPoseNumbers)
    ? uniqueSorted(posePolicy.requiredPoseNumbers.map(toPoseNumber).filter((value) => value !== null))
    : [];

  if (resolvedRequired.length > 0) {
    requiredPoseNumbers = resolvedRequired;
    requiredPoseSource = 'w0-v3';
  }

  bookId = toStringValue(bookConfigRef.bookId) || bookId;
  formatId = toStringValue(bookConfigRef.formatId) || formatId;
}

const manifest2bKey = extractManifestKey(ctx.manifest2bKey || ctx.manifest2bUrl) || `${bookId}/orders/${String(orderId)}/manifests/2b-manifest.json`;

let existing2b = null;
try {
  const maybe = $items('Download 2B Manifest (optional)', 0, $runIndex)?.[0]?.json;
  if (maybe && maybe.schema === 'lhb.run-manifest@v2.0') existing2b = maybe;
} catch {}

const existingEntries = Array.isArray(existing2b?.entries) ? existing2b.entries.filter((entry) => entry && typeof entry === 'object') : [];
const existingByPose = new Map(existingEntries.map((entry) => [Number(entry.poseNumber), entry]));
const approvedEntries = Array.isArray(manifest2a.entries)
  ? manifest2a.entries.filter((entry) => entry && typeof entry === 'object' && entry.approved === true && String(entry.status || '').toLowerCase() === 'approved')
  : [];
const approvedByPose = new Map();
for (const entry of approvedEntries) {
  const poseNumber = toPoseNumber(entry.poseNumber);
  const approvedKey = toStringValue(entry.approvedKey);
  if (poseNumber === null || !approvedKey) continue;
  approvedByPose.set(poseNumber, entry);
}

const targetEntries = requiredPoseNumbers
  .map((poseNumber) => approvedByPose.get(poseNumber))
  .filter(Boolean);
const missingRequiredPoseNumbers = requiredPoseNumbers.filter((poseNumber) => !approvedByPose.has(poseNumber));

if (targetEntries.length === 0) {
  return [{ json: {
    orderId,
    characterHash,
    scheduled: 0,
    reason: approvedEntries.length === 0 ? 'NO_APPROVED_POSES' : 'NO_REQUIRED_POSES_READY',
    totalApproved: 0,
    skippedByBriaStatus: 0,
    skippedBy2BManifest: 0,
    skippedTotal: 0,
    requiredPoseNumbers,
    requiredPoseSource,
    missingRequiredPoseNumbers,
    manifest2bKey,
    manifest2aUrl,
    bookId,
    formatId,
  } }];
}

const force = !!ctx.force;
let skippedCount = 0;
let skippedByBriaStatus = 0;
let skippedBy2BManifest = 0;

const work = targetEntries
  .filter((entry) => {
    if (force) return true;
    const poseNum = Number(entry.poseNumber);
    const ex = existingByPose.get(poseNum);
    if (!ex) return true;
    const srcKey = entry.approvedKey || null;
    const srcReplacedAt = entry.replacedAt || null;
    const srcReplacementCount = Number(entry.replacementCount || 0);
    const briaStatus = String(ex.briaStatus || '').toLowerCase();
    const done = !!(
      ex.bgRemovedKey &&
      briaStatus === 'completed' &&
      (ex.sourceApprovedKey || null) === srcKey &&
      ((ex.sourceReplacedAt || null) === srcReplacedAt || Number(ex.sourceReplacementCount || 0) === srcReplacementCount)
    );
    if (done) {
      skippedBy2BManifest++;
      skippedCount++;
    } else if (briaStatus === 'completed') {
      skippedByBriaStatus++;
    }
    return !done;
  })
  .map((entry) => ({
    orderId,
    characterHash,
    poseNumber: Number(entry.poseNumber),
    approvedKey: entry.approvedKey,
    replacedAt: entry.replacedAt || null,
    replacementCount: Number(entry.replacementCount || 0),
    manifest2aKey,
    manifest2aUrl,
    manifest2bKey,
    oneManifestKey,
    oneManifestUrl: oneManifestKey ? toManifestUrl(backendUrl, oneManifestKey) : (ctx.oneManifestUrl || null),
    requiredPoseNumbers,
    requiredPoseSource,
    missingRequiredPoseNumbers,
    bookId,
    formatId,
    backendUrl,
    callbackUrl,
    force,
  }));

if (work.length === 0) {
  return [{ json: {
    orderId,
    characterHash,
    scheduled: 0,
    reason: 'ALL_POSES_ALREADY_PROCESSED',
    totalApproved: targetEntries.length,
    skippedByBriaStatus,
    skippedBy2BManifest,
    skippedTotal: skippedCount,
    requiredPoseNumbers,
    requiredPoseSource,
    missingRequiredPoseNumbers,
    manifest2bKey,
    manifest2aUrl,
    bookId,
    formatId,
  } }];
}

return work.map((item) => ({ json: item }));

/**
 * Final response payload (does not wait for workers).
 */
const items = $items('Build Worklist', 0, $runIndex) || [];
let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}
const explicitScheduled = Number(items[0]?.json?.scheduled);
const scheduled = Number.isFinite(explicitScheduled) ? explicitScheduled : items.length;
return [{ json: { orderId: ctx.orderId, scheduled, callbackUrl: ctx.callbackUrl, batchSize: ctx.batchSize } }];

/**
 * Normalize Result - Extract and normalize sub-workflow output for aggregator.
 * Preserves manifest key + required-pose context from the worklist item.
 */
const j = $json || {};
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');
let result = j.result || j;

let ctx = {};
try { ctx = $items('Normalize 2B Input', 0, $runIndex)?.[0]?.json || {}; } catch {}

const orderId = pick(result.orderId, j.orderId, ctx.orderId, null);
const characterHash = pick(result.characterHash, j.characterHash, ctx.characterHash, null);
const poseNumberRaw = pick(result.poseNumber, j.poseNumber, null);
const poseNumber = (poseNumberRaw === 0 || poseNumberRaw === '0') ? 0 : Number(poseNumberRaw);

if (!orderId) throw new Error('2B aggregator: orderId required');
if (!characterHash) throw new Error('2B aggregator: characterHash required');
if (!Number.isFinite(poseNumber)) throw new Error('2B aggregator: poseNumber required');

const backendUrl = pick(result.backendUrl, j.backendUrl, ctx.backendUrl, 'https://admin.littleherolabs.com');
const manifest2aUrl = pick(result.manifest2aUrl, j.manifest2aUrl, ctx.manifest2aUrl, ctx.manifestUrl, null);
const manifest2aKey = pick(result.manifest2aKey, j.manifest2aKey, ctx.manifest2aKey, null);
const manifest2bKey = pick(result.manifest2bKey, j.manifest2bKey, ctx.manifest2bKey, null);
const requiredPoseNumbers = Array.isArray(result.requiredPoseNumbers)
  ? result.requiredPoseNumbers
  : (Array.isArray(j.requiredPoseNumbers)
    ? j.requiredPoseNumbers
    : (Array.isArray(ctx.requiredPoseNumbers) ? ctx.requiredPoseNumbers : []));
const missingRequiredPoseNumbers = Array.isArray(result.missingRequiredPoseNumbers)
  ? result.missingRequiredPoseNumbers
  : (Array.isArray(j.missingRequiredPoseNumbers)
    ? j.missingRequiredPoseNumbers
    : (Array.isArray(ctx.missingRequiredPoseNumbers) ? ctx.missingRequiredPoseNumbers : []));

const normalizedResult = {
  orderId,
  characterHash,
  poseNumber,
  manifest2aUrl,
  manifest2aKey,
  manifest2bKey,
  oneManifestKey: pick(result.oneManifestKey, j.oneManifestKey, ctx.oneManifestKey, null),
  oneManifestUrl: pick(result.oneManifestUrl, j.oneManifestUrl, ctx.oneManifestUrl, null),
  requiredPoseNumbers,
  requiredPoseSource: pick(result.requiredPoseSource, j.requiredPoseSource, ctx.requiredPoseSource, 'legacy-default'),
  missingRequiredPoseNumbers,
  bookId: pick(result.bookId, j.bookId, ctx.bookId, null),
  formatId: pick(result.formatId, j.formatId, ctx.formatId, null),
  approvedKey: pick(result.approvedKey, null),
  sourceReplacedAt: pick(result.sourceReplacedAt, null),
  sourceReplacementCount: Number(pick(result.sourceReplacementCount, 0) || 0),
  sourceUrl: pick(result.sourceUrl, null),
  briaStatus: pick(result.briaStatus, 'error'),
  briaRequestId: pick(result.briaRequestId, null),
  briaStatusUrl: pick(result.briaStatusUrl, null),
  briaCompletedAt: pick(result.briaCompletedAt, null),
  briaErrorMessage: pick(result.briaErrorMessage, null),
  bgRemovedKey: pick(result.bgRemovedKey, null),
  bgRemovedContentType: pick(result.bgRemovedContentType, null),
  bgRemovedSizeBytes: (result.bgRemovedSizeBytes === 0 ? 0 : (Number(result.bgRemovedSizeBytes) || null)),
  bgRemovedImageUrl: pick(result.bgRemovedImageUrl, null),
  qa: (result.qa && typeof result.qa === 'object') ? result.qa : null,
  needsReview: !!pick(result.needsReview, false),
  reviewReason: pick(result.reviewReason, null),
};

return [{ json: { backendUrl, manifest2aUrl, manifest2aKey, manifest2bKey, requiredPoseNumbers, requiredPoseSource: normalizedResult.requiredPoseSource, result: normalizedResult } }];

/**
 * Merge the incoming pose result into 2B manifest (create if missing).
 * Summary completeness now follows the required pose contract resolved from W0
 * when that context is present on the work item.
 */
let ctx = {};
try { ctx = $items('Normalize Result', 0, $runIndex)?.[0]?.json || {}; } catch {}
const incoming = ctx.result || {};

const orderId = incoming.orderId || ctx.orderId || null;
if (!orderId) throw new Error('2B aggregator: missing orderId in Normalize Result');

const LEGACY_REQUIRED_POSES = Array.from({ length: 12 }, (_, index) => index + 1);
const toObject = (value) => (value && typeof value === 'object' && !Array.isArray(value) ? value : null);
const toStringValue = (value) => {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
};
const toPoseNumber = (value) => {
  if (typeof value === 'number' && Number.isInteger(value) && value >= 0) return value;
  if (typeof value !== 'string' || value.trim().length === 0) return null;
  const parsed = Number.parseInt(value, 10);
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : null;
};
const uniqueSorted = (values) => [...new Set(values)].sort((left, right) => left - right);
const extractManifestKey = (value) => {
  const raw = toStringValue(value);
  if (!raw) return null;
  const withoutQuery = raw.split('?')[0];
  const marker = '/api/manifests/';
  if (withoutQuery.includes(marker)) {
    return withoutQuery.split(marker)[1].replace(/^\/+/, '');
  }
  try {
    if (withoutQuery.startsWith('http://') || withoutQuery.startsWith('https://')) {
      const url = new URL(withoutQuery);
      return url.pathname.replace(/^\/api\/manifests\//, '').replace(/^\/+/, '');
    }
  } catch {}
  return withoutQuery.replace(/^\/+/, '');
};
const toManifestUrl = (base, manifestKey) => {
  const normalizedBase = String(base || 'https://admin.littleherolabs.com').replace(/\/$/, '');
  const normalizedKey = String(manifestKey || '').replace(/^\/+/, '');
  return `${normalizedBase}/api/manifests/${normalizedKey}`;
};
function asManifest(raw) {
  if (!raw) return null;
  if (raw.schema) return raw;
  const text = typeof raw === 'string' ? raw : (raw.data || raw.body || null);
  if (!text || typeof text !== 'string') return null;
  try {
    const parsed = JSON.parse(text);
    return parsed && parsed.schema ? parsed : null;
  } catch {
    return null;
  }
}

const backendUrl = ctx.backendUrl || incoming.backendUrl || 'https://admin.littleherolabs.com';
const manifest2bMaybe = $items('Download 2B Manifest (if exists)', 0, $runIndex)?.[0]?.json || null;
const manifest2aHint = incoming.manifest2aUrl || ctx.manifest2aUrl || (incoming.manifest2aKey ? toManifestUrl(backendUrl, incoming.manifest2aKey) : null);
const isFullUrl = String(manifest2aHint || '').indexOf('https://') === 0 || String(manifest2aHint || '').indexOf('http://') === 0;
const resolvedManifest2aUrl = isFullUrl
  ? String(manifest2aHint)
  : toManifestUrl(backendUrl, String(manifest2aHint || '').replace(/^\/+/, ''));

let manifest2a = null;
try {
  manifest2a = asManifest($items('Download 2A Manifest (for merge)', 0, $runIndex)?.[0]?.json);
} catch {}

if (!manifest2a) {
  try {
    const url = resolvedManifest2aUrl + (resolvedManifest2aUrl.includes('?') ? '&' : '?') + 'v=' + Date.now();
    const raw = await this.helpers.httpRequest({ method: 'GET', url, json: false, timeout: 90000 });
    manifest2a = asManifest(raw);
  } catch {}
}

if (!manifest2a) {
  try { manifest2a = asManifest($items('Download 2A Manifest', 0, $runIndex)?.[0]?.json); } catch {}
}
if (!manifest2a) {
  try { manifest2a = asManifest($items('Download 2A Manifest', 0, 0)?.[0]?.json); } catch {}
}

if (!incoming || !incoming.characterHash || !Number.isFinite(Number(incoming.poseNumber))) {
  throw new Error('2B aggregator: invalid Normalize Result payload');
}

if (!manifest2a || !manifest2a.schema) {
  throw new Error('2B aggregator: missing 2A manifest or invalid schema (orderId=' + orderId + ', manifest2aUrl=' + resolvedManifest2aUrl + ')');
}

let manifest2b = (manifest2bMaybe && manifest2bMaybe.schema === 'lhb.run-manifest@v2.0') ? manifest2bMaybe : null;
if (!manifest2b) {
  manifest2b = JSON.parse(JSON.stringify(manifest2a));
  manifest2b.stage = '2b';
  manifest2b.createdAt = new Date().toISOString();
  manifest2b.updatedAt = new Date().toISOString();
  (manifest2b.entries || []).forEach((entry) => {
    entry.bgRemovedKey = null;
    entry.bgRemovedImageUrl = null;
    entry.briaStatus = null;
    entry.briaRequestId = null;
    entry.briaStatusUrl = null;
    entry.briaErrorMessage = null;
    entry.sourceApprovedKey = null;
    entry.sourceReplacedAt = null;
    entry.sourceReplacementCount = 0;
    entry.processedAt = null;
    entry.needsReview = false;
    entry.reviewReason = null;
    entry.isFlagged = false;
  });
}

manifest2b.entries = Array.isArray(manifest2b.entries)
  ? manifest2b.entries.filter((entry) => entry && typeof entry === 'object')
  : [];
const entryByPose = new Map();
for (const entry of manifest2b.entries) {
  const poseNumber = toPoseNumber(entry.poseNumber);
  if (poseNumber === null) continue;
  entryByPose.set(poseNumber, entry);
}

const poseNumber = Number(incoming.poseNumber);
const entry = entryByPose.get(poseNumber);
if (!entry) throw new Error('2B aggregator: pose ' + poseNumber + ' not found in manifest entries');

entry.sourceApprovedKey = incoming.approvedKey || entry.approvedKey || null;
entry.sourceReplacedAt = incoming.sourceReplacedAt || null;
entry.sourceReplacementCount = Number(incoming.sourceReplacementCount || 0);
entry.processedAt = new Date().toISOString();
entry.briaStatus = incoming.briaStatus;
entry.briaRequestId = incoming.briaRequestId || null;
entry.briaStatusUrl = incoming.briaStatusUrl || null;
entry.briaErrorMessage = incoming.briaErrorMessage || null;
if (incoming.qa && typeof incoming.qa === 'object') {
  entry.qa = { ...(entry.qa || {}), ...incoming.qa };
}

if (incoming.briaStatus === 'completed') {
  entry.bgRemovedKey = incoming.bgRemovedKey || entry.bgRemovedKey;
  entry.bgRemovedImageUrl = incoming.bgRemovedImageUrl || entry.bgRemovedImageUrl;
  entry.bgRemovedStatus = 'completed';
  entry.bgRemoved = true;
  entry.needsReview = incoming.needsReview === true;
  entry.reviewReason = incoming.needsReview === true ? (incoming.reviewReason || 'transparency_fail_or_low_conf') : null;
  if (incoming.needsReview !== true) entry.isFlagged = false;
} else {
  entry.bgRemoved = false;
  entry.bgRemovedStatus = incoming.briaStatus;
  entry.needsReview = true;
  entry.reviewReason = incoming.reviewReason || 'unknown';
}

const incomingRequiredPoseNumbers = Array.isArray(incoming.requiredPoseNumbers)
  ? incoming.requiredPoseNumbers
